import 'package:flutter/material.dart'; import 'package:share_plus/share_plus.dart'; import '../services/favorite_ayah_service.dart';
class FavoriteAyahsPage extends StatefulWidget{const FavoriteAyahsPage({super.key});@override State<FavoriteAyahsPage> createState()=>_FavoriteAyahsPageState();}
class _FavoriteAyahsPageState extends State<FavoriteAyahsPage>{List<FavoriteAyah> favorites=[];bool loading=true;@override void initState(){super.initState();load();}Future<void> load()async{final d=await FavoriteAyahService.loadFavorites();if(!mounted)return;setState((){favorites=d;loading=false;});}@override Widget build(BuildContext context){if(loading)return const Center(child:CircularProgressIndicator());if(favorites.isEmpty)return const Center(child:Text('لا توجد آيات مفضلة بعد'));return ListView(padding:const EdgeInsets.all(16),children:favorites.map((item)=>Card(child:ListTile(title:Text('سورة ${item.surahName}، آية ${item.ayahNumber}'),subtitle:Text(item.text,maxLines:2,overflow:TextOverflow.ellipsis),trailing:IconButton(icon:const Icon(Icons.share),onPressed:()=>Share.share('${item.text}  ﴿${item.ayahNumber}﴾\nسورة ${item.surahName}\n\nمن تطبيق وردي'))))).toList());}}
